//! What every command is: a DTO with metadata ([`CommandInfo`], generated by `#[cmd]`) and
//! behavior ([`Run`], written by hand), plus the boundary between JSON and the typed DTOs.

use std::future::Future;
use std::pin::Pin;

use polarion::Polarion;
use schemars::JsonSchema;
use schemars::generate::SchemaSettings;
use serde::Serialize;
use serde::de::DeserializeOwned;
use serde_json::{Map, Value};

use crate::error::{CommandError, Result};
use crate::files::LocalFiles;
use crate::{AnyCommand, AnyOutput, View};

/// A command's metadata, generated by `#[cmd]`.
pub trait CommandInfo {
    /// Kebab-case name within the area (from the type name), e.g. `add-assignee`.
    const NAME: &'static str;
    /// The first paragraph of the doc comment.
    const SUMMARY: &'static str;
    /// The summary, plus a note for commands that modify data.
    const DESCRIPTION: &'static str;
    /// Modifies data (refused unless writes are enabled for the target).
    const WRITE: bool;
    /// How the command line shows the result.
    const VIEW: View;
}

/// What a command does.
pub trait Run: Sized {
    /// The result, serialized only at the boundary (JSON for MCP and `--json`, ...); its
    /// JSON Schema describes that serialized form (MCP output schemas).
    type Output: Serialize + JsonSchema + Send;

    fn run(self, cx: &Context<'_>) -> impl Future<Output = Result<Self::Output>> + Send;
}

/// A running command whose result is an [`AnyOutput`].
pub(crate) type BoxedRun<'a> = Pin<Box<dyn Future<Output = Result<AnyOutput>> + Send + 'a>>;

/// [`Run::run`] on the heap, for `AnyCommand::run`, which picks one of some 250 commands and
/// awaits it once. Unoptimized builds give every temporary of a function a stack slot of its
/// own: built in `AnyCommand::run`, the futures of all commands (a few KB each) would be in its
/// frame at once, more than the 1 MB stack of the main thread on Windows leaves room for. Built
/// here, each takes a pointer there.
pub(crate) fn boxed<'a, C: Run + 'a>(
    command: C,
    cx: &'a Context<'_>,
    output: fn(C::Output) -> AnyOutput,
) -> BoxedRun<'a> {
    let run = command.run(cx);
    Box::pin(async move { run.await.map(output) })
}

/// What commands run against: the client, the default project for short references, and the
/// local files commands may read and write.
#[derive(Clone, Copy)]
pub struct Context<'a> {
    pub polarion: &'a Polarion,
    pub default_project: Option<&'a str>,
    /// The files commands that take a path (`file`, `dir`) may use: none unless
    /// [`Context::with_files`] says otherwise.
    pub files: LocalFiles<'a>,
}

impl std::fmt::Debug for Context<'_> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Context")
            .field("default_project", &self.default_project)
            .field("files", &self.files)
            .finish_non_exhaustive()
    }
}

impl<'a> Context<'a> {
    pub fn new(polarion: &'a Polarion, default_project: Option<&'a str>) -> Self {
        Self {
            polarion,
            default_project,
            files: LocalFiles::Refused,
        }
    }

    /// The context with these local files for commands that take a path.
    pub fn with_files(self, files: LocalFiles<'a>) -> Self {
        Self { files, ..self }
    }

    /// `given`, or the default project.
    pub fn project(&self, given: Option<&str>) -> Result<String> {
        given
            .or(self.default_project)
            .map(str::to_owned)
            .ok_or_else(|| {
                CommandError::invalid(
                    "no project: pass `project`, set POLARION_PROJECT (or -p), or use PROJECT/ID",
                )
            })
    }

    /// `given`, or the default project, if any.
    pub fn opt_project(&self, given: Option<&str>) -> Option<String> {
        given.or(self.default_project).map(str::to_owned)
    }

    /// The default project for a short reference such as `what`.
    pub(crate) fn default_project_for(&self, what: &str) -> Result<&'a str> {
        self.default_project.ok_or_else(|| {
            CommandError::invalid(format!(
                "no project for `{what}`: give the project in it, or set POLARION_PROJECT (or -p)"
            ))
        })
    }
}

/// One catalog entry: a command's metadata and how to build it from JSON.
#[derive(Clone, Copy)]
pub struct Entry {
    /// Area, e.g. `items`; the full name is `area.name`.
    pub area: &'static str,
    /// Kebab-case name within the area, e.g. `back-links`.
    pub name: &'static str,
    pub summary: &'static str,
    /// The summary, plus a note for commands that modify data.
    pub description: &'static str,
    /// Modifies data (refused unless writes are enabled for the target).
    pub write: bool,
    pub view: View,
    /// JSON Schema of the arguments object.
    pub schema: fn() -> Value,
    /// JSON Schema of the serialized result.
    pub output: fn() -> Value,
    /// The typed command from JSON arguments.
    pub parse: fn(Value) -> Result<AnyCommand>,
}

impl std::fmt::Debug for Entry {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Entry")
            .field("name", &self.full_name())
            .field("write", &self.write)
            .finish_non_exhaustive()
    }
}

impl Entry {
    /// `area.name`.
    pub fn full_name(&self) -> String {
        format!("{}.{}", self.area, self.name)
    }

    /// JSON Schema of the arguments object.
    pub fn input_schema(&self) -> Value {
        (self.schema)()
    }

    /// JSON Schema of the serialized result.
    pub fn output_schema(&self) -> Value {
        (self.output)()
    }

    /// The typed command from JSON arguments (an object, or `null` for none).
    pub fn parse(&self, arguments: Value) -> Result<AnyCommand> {
        (self.parse)(arguments)
    }
}

/// The JSON Schema of a DTO's arguments, with every subschema inlined.
pub fn schema_of<T: JsonSchema>() -> Value {
    let generator = SchemaSettings::draft2020_12()
        .with(|s| s.inline_subschemas = true)
        .into_generator();
    let mut schema = generator.into_root_schema_for::<T>().to_value();
    if let Some(object) = schema.as_object_mut() {
        for key in ["$schema", "title", "description"] {
            object.remove(key);
        }
        object
            .entry("properties")
            .or_insert_with(|| Value::Object(Map::new()));
        object.insert("additionalProperties".into(), Value::Bool(false));
    }
    schema
}

/// The JSON Schema of a result as it is serialized. Types used more than once (users, enum
/// options, rich text, ...) are `$defs`, referenced from where they appear.
pub fn output_schema_of<T: JsonSchema>() -> Value {
    let generator = SchemaSettings::draft2020_12()
        .for_serialize()
        .into_generator();
    let mut schema = generator.into_root_schema_for::<T>().to_value();
    if let Some(object) = schema.as_object_mut() {
        for key in ["$schema", "title"] {
            object.remove(key);
        }
    }
    schema
}

/// A DTO from JSON arguments: unknown keys are refused, `null` counts as absent, and scalars are
/// accepted in the forms people and agents tend to send (`"5"` for 5, `"a,b"` for a list).
pub fn parse_as<T: DeserializeOwned + JsonSchema>(arguments: Value) -> Result<T> {
    let mut map = match arguments {
        Value::Object(map) => map,
        Value::Null => Map::new(),
        other => {
            return Err(CommandError::invalid(format!(
                "arguments must be an object, got {other}"
            )));
        }
    };
    let schema = schema_of::<T>();
    let empty = Map::new();
    let properties = schema
        .get("properties")
        .and_then(Value::as_object)
        .unwrap_or(&empty);
    map.retain(|_, v| !v.is_null());
    if let Some(unknown) = map.keys().find(|k| !properties.contains_key(*k)) {
        let known: Vec<&str> = properties.keys().map(String::as_str).collect();
        return Err(CommandError::invalid(if known.is_empty() {
            format!("unknown argument `{unknown}` (this command takes none)")
        } else {
            format!(
                "unknown argument `{unknown}` (expected: {})",
                known.join(", ")
            )
        }));
    }
    for (key, value) in &mut map {
        normalize(&properties[key], value).map_err(|expected| {
            CommandError::invalid(format!("`{key}`: expected {expected}, got {value}"))
        })?;
    }
    serde_path_to_error::deserialize(Value::Object(map)).map_err(|e| {
        let path = e.path().to_string();
        let inner = e.into_inner();
        CommandError::invalid(if path == "." {
            format!("invalid arguments: {inner}")
        } else {
            format!("`{path}`: {inner}")
        })
    })
}

/// Bring a JSON value into the scalar type its schema asks for, where that is unambiguous;
/// `Err` names the expected type when a string cannot be one.
fn normalize(schema: &Value, value: &mut Value) -> std::result::Result<(), &'static str> {
    let types: Vec<&str> = match schema.get("type") {
        Some(Value::String(t)) => vec![t.as_str()],
        Some(Value::Array(ts)) => ts.iter().filter_map(Value::as_str).collect(),
        _ => Vec::new(),
    };
    let wants = |t: &str| types.contains(&t);
    let converted = match &*value {
        Value::String(s) if wants("integer") => s.trim().parse::<i64>().ok().map(Value::from),
        Value::String(s) if wants("number") => s.trim().parse::<f64>().ok().map(Value::from),
        Value::String(s) if wants("boolean") => match s.trim() {
            "true" | "1" | "yes" => Some(Value::Bool(true)),
            "false" | "0" | "no" => Some(Value::Bool(false)),
            _ => None,
        },
        Value::String(s) if wants("array") => Some(Value::Array(
            crate::config::split_list(s)
                .into_iter()
                .map(Value::String)
                .collect(),
        )),
        Value::Number(_) | Value::Bool(_)
            if wants("string") && !wants("integer") && !wants("number") && !wants("boolean") =>
        {
            Some(Value::String(value.to_string()))
        }
        _ => None,
    };
    if let Some(converted) = converted {
        *value = converted;
        return Ok(());
    }
    // A string that should have been a number or a flag.
    if value.is_string() && !wants("string") && !wants("array") && !wants("object") {
        if wants("integer") {
            return Err("an integer");
        }
        if wants("number") {
            return Err("a number");
        }
        if wants("boolean") {
            return Err("true or false");
        }
    }
    Ok(())
}
